package lru

import "container/list"

// LRUCache is a fixed-capacity least-recently-used cache mapping int keys to
// int values.
type LRUCache struct {
	capacity int
	order    *list.List // front = least recently used, back = most recently used
	data     map[int]*list.Element
}

// NewLRUCache returns a new cache that holds at most capacity entries.
func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		order:    list.New(),
		data:     make(map[int]*list.Element, capacity),
	}
}

// Get returns the value for key and whether it was present. A successful Get
// counts as a use of key for eviction purposes.
func (c *LRUCache) Get(key int) (int, bool) {
	if el, ok := c.data[key]; ok {
		c.order.MoveToBack(el)
		return el.Value.(int), true
	}
	return 0, false
}

// Put inserts or updates the value for key, evicting the least recently used
// entry if the cache is over capacity.
func (c *LRUCache) Put(key, value int) {
	if el, ok := c.data[key]; ok {
		el.Value = value
		c.order.MoveToBack(el)
		return
	}
	el := c.order.PushBack(value)
	c.data[key] = el

	if c.order.Len() > c.capacity {
		oldest := c.order.Front()
		c.order.Remove(oldest)
		delete(c.data, oldest.Value.(int))
	}
}

package lru

import "testing"

func TestGetMarksKeyAsRecentlyUsed(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 1)
	c.Put(2, 2)
	if v, ok := c.Get(1); !ok || v != 1 {
		t.Fatalf("Get(1) = %d, %v; want 1, true", v, ok)
	}
	// 1 was just read, so 2 is the least recently used entry.
	c.Put(3, 3)
	if _, ok := c.Get(2); ok {
		t.Error("key 2 was evicted; want it evicted (least recently used)")
	}
	if _, ok := c.Get(2); ok {
		t.Error("key 2 should have been evicted")
	}
	if v, ok := c.Get(1); !ok || v != 1 {
		t.Fatalf("Get(1) after eviction = %d, %v; want 1, true", v, ok)
	}
	if v, ok := c.Get(3); !ok || v != 3 {
		t.Fatalf("Get(3) = %d, %v; want 3, true", v, ok)
	}
}

func TestGetAbsentKey(t *testing.T) {
	c := NewLRUCache(1)
	c.Put(1, 1)
	if v, ok := c.Get(42); ok || v != 0 {
		t.Fatalf("Get(42) = %d, %v; want 0, false", v, ok)
	}
}

func TestPutExistingKeyUpdatesWithoutEviction(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(1, 10)
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Fatalf("Get(1) = %d, %v; want 10, true", v, ok)
	}
	if v, ok := c.Get(2); !ok || v != 2 {
		t.Fatalf("Get(2) = %d, %v; want 2, true", v, ok)
	}
}

func TestPutExistingKeyRefreshesRecency(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(2, 20) // 2 becomes most recently used
	c.Put(3, 3)  // evicts 1
	if _, ok := c.Get(1); ok {
		t.Error("key 1 should have been evicted")
	}
	if v, ok := c.Get(2); !ok || v != 20 {
		t.Fatalf("Get(2) = %d, %v; want 20, true", v, ok)
	}
}

func TestEvictionOrderAcrossGetsAndPuts(t *testing.T) {
	c := NewLRUCache(3)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(3, 3)
	c.Get(1) // order: 2, 3, 1
	c.Get(2) // order: 3, 1, 2
	c.Put(4, 4) // evicts 3
	if _, ok := c.Get(3); ok {
		t.Error("key 3 should have been evicted")
	}
	for k, want := range map[int]int{1: 1, 2: 2, 4: 4} {
		if v, ok := c.Get(k); !ok || v != want {
			t.Errorf("Get(%d) = %d, %v; want %d, true", k, v, ok, want)
		}
	}
}

